function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree has at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 200) return 'The tree has at most 200 nodes.';
  if (values.some(v => v !== 0 && v !== 1)) return 'Each node value is 0 or 1.';
  return null;
}

