function pruneTree(root) {
  // Copy only the nodes whose own subtree still holds a 1, checking each subtree from scratch.
  const hasOne = node => node !== null && (node.val === 1 || hasOne(node.left) || hasOne(node.right));
  const copy = node => hasOne(node) ? new TreeNode(node.val, copy(node.left), copy(node.right)) : null;
  return copy(root);
}

