function generate(rand, size) {
  const n = size === 'large' ? 150 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 12);
  // Attach each new node to a free child slot; a high bias favours recent slots and grows long branches.
  const bias = rand();
  const nodes = [{ val: 0, left: null, right: null }], slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Ones are sparse in some trees and common in others, so both big prunes and small ones happen.
  const chance = size === 'large' ? 0.01 + rand() * 0.2 : rand() * 0.6;
  for (const node of nodes) node.val = rand() < chance ? 1 : 0;
  const out = [], queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
